export const getSubsidiBySlug = (slug: string): SubsidyCountryData | null => {
  if (!slug) return null;
  const s = slug.toLowerCase().trim();
  const stripped = s.replace(/^republik\s+/, '').replace(/^republic of\s+/, '').trim();
  return (
    DATABASE_ALOKASI_SUBSIDI[s] ||
    DATABASE_ALOKASI_SUBSIDI[s.replace(/[\s-]+/g, '_')] ||
    DATABASE_ALOKASI_SUBSIDI[s.replace(/[\s_]+/g, '-')] ||
    DATABASE_ALOKASI_SUBSIDI[stripped] ||
    DATABASE_ALOKASI_SUBSIDI[stripped.replace(/[\s-]+/g, '_')] ||
    DATABASE_ALOKASI_SUBSIDI[stripped.replace(/[\s_]+/g, '-')] ||
    null
  );
};
